import static cn.zj.zjmarket.verification.ProductCommands.*;
/** Isolated owned fixtures; actual MySQL/channel, controlled A evidence, two separate JVMs. */
public final class FulfillmentCommands {
 private static final ObjectMapper JSON=new ObjectMapper();
 private static String id(){return UUID.randomUUID().toString();}
 private static long count(JdbcTemplate db,String sql,Object...a){return db.queryForObject(sql,Long.class,a);}
 private static TradeReceipt completed(MarketOrder o,String version)throws Exception{return SettlementCommands.wire(id(),"TEAM_COMPLETED",Map.of("teamId",o.evidence().teamId(),"activityId",o.evidence().activityId(),"teamVersion",version,"outTradeNoList",List.of(o.orderId())),null);}
 private static TradeReceipt query(MarketOrder o,Channel c,String event,String version)throws Exception{var old=SettlementCommands.receipt(o,c,event,id(),"IGNORED");var e=(ObjectNode)JSON.readTree(old.body());((ObjectNode)e.path("payload").path("result")).put("teamStatus","COMPLETED").put("teamVersion",version);byte[] b=new ContractCodec().encode(e);return new TradeReceipt(old.producer(),old.eventId(),old.type(),ContractCodec.sha256(b),new String(b,java.nio.charset.StandardCharsets.UTF_8),event);}
 private static DataSource failFulfillmentInsert(DataSource ds){return new org.springframework.jdbc.datasource.DelegatingDataSource(ds){@Override public java.sql.Connection getConnection()throws java.sql.SQLException{var c=super.getConnection();return (java.sql.Connection)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{java.sql.Connection.class},(proxy,m,args)->{try{if(m.getName().equals("prepareStatement")&&args[0] instanceof String sql&&sql.startsWith("INSERT INTO b_fulfillment"))throw new java.sql.SQLException("Owned insertion fault","45000");return m.invoke(c,args);}catch(java.lang.reflect.InvocationTargetException wrapped){throw wrapped.getCause();}});}};}
 private static String work(JdbcTemplate db,String order,String version){return db.queryForObject("SELECT work_id FROM b_trade_work WHERE order_id=? AND kind='TEAM_COMPLETED' AND JSON_UNQUOTE(JSON_EXTRACT(CONVERT(evidence USING utf8mb4),'$.payload.teamVersion'))=?",String.class,order,version);}
 private static void due(JdbcTemplate db,String id){db.update("UPDATE b_trade_work SET next_attempt_ms=0 WHERE work_id=? AND state='WAITING_DEPENDENCY'",id);}
 public static void browserTick(org.springframework.context.ConfigurableApplicationContext ctx,Path work,String actor,String order)throws Exception{
  if(!Files.exists(work.resolve("browser-fulfill.txt")))return;var ds=ctx.getBean(DataSource.class);var db=new JdbcTemplate(ds);if(count(db,"SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",order)>0)return;var pay=ctx.getBean(IPaymentRepository.class);var payment=pay.forOrder(actor,order);if(payment==null||!payment.aAcceptance().equals("ACCEPTED"))return;var o=pay.order(actor,order);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);var settlement=new SettlementRepository(ds,tx,ctx.getBean(IOrderRepository.class),"zj-market","s01","c01");var repo=new FulfillmentRepository(ds,tx,ctx.getBean(IOrderRepository.class),settlement);settlement.receive(completed(o,"3"));var w=repo.claim(work(db,order,"3"));if(w!=null){var fact=((IChannelFacts)ctx.getBean(ISimulatedChannel.class)).fact(payment.paymentId(),payment.successAttemptId());repo.complete(w,query(o,fact.channel(),w.payment().eventId(),"3"));}
 }
 public static int run(String mode){try{
  check(Set.of("verify","recover").contains(mode),"known fulfillment mode");check(env("B_DATABASE_SCOPE").equals("b02-test")&&env("B_DATABASE_USERNAME").equals("zj_market_b02_test_app")&&env("B_DATABASE_URL").matches("^jdbc:mysql://[^/]+/zj_market_b02_test(?:\\?.*)?$"),"exact isolated fulfillment database");Path dir=Path.of(env("B_PAYMENT_WORK"));PaymentCommands.offline=mode.equals("recover");
  try(var ctx=new SpringApplication(PaymentCommands.ProbeConfiguration.class,OrderCommands.ProbeConfiguration.class,ZjMarketApplication.class).run("--server.port=0","--b.identity.enabled=true","--b.product.enabled=true","--b.inventory.enabled=true","--b.order.enabled=true","--b.trade.enabled=true","--b.trade.scheduler-enabled=false","--b.payment.enabled=true","--b.payment.checkout-enabled="+!mode.equals("recover"),"--b.payment.scheduler-enabled=false","--b.trade.events-enabled=false","--b.trial.enabled=false","--b.sync.enabled=false","--b.infrastructure.database.enabled=true","--b.infrastructure.rpc.enabled=false","--b.infrastructure.mq.enabled=false")){
   var ds=ctx.getBean(DataSource.class);var db=new JdbcTemplate(ds);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);var orders=ctx.getBean(IOrderRepository.class);var pay=ctx.getBean(IPaymentRepository.class);var payments=ctx.getBean(IPaymentService.class);var channel=(IChannelFacts)ctx.getBean(ISimulatedChannel.class);var settlement=new SettlementRepository(ds,tx,orders,"zj-market","s01","c01");var repo=new FulfillmentRepository(ds,tx,orders,settlement);
   if(mode.equals("recover")){
    var f=JSON.readTree(Files.readAllBytes(dir.resolve("restart.json")));String actor=f.path("actor").asText(),order=f.path("order").asText(),payment=f.path("payment").asText(),attempt=f.path("attempt").asText(),wid=f.path("work").asText();check(count(db,"SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",order)==0,"uncommitted fulfillment absent after JVM restart");db.update("UPDATE b_trade_work SET next_attempt_ms=0,lease_until_ms=0 WHERE work_id=? AND lease_token=?",wid,f.path("token").asText());var w=repo.claim(wid);check(w!=null,"new JVM reclaims original durable work with checkout disabled");repo.complete(w,query(pay.order(actor,order),channel.fact(payment,attempt).channel(),w.payment().eventId(),"4"));check(pay.order(actor,order).businessStatus().equals("GROUP_COMPLETED")&&count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='CONFIRM'",order)==1,"new JVM completes exactly once");settlement.applyInbox(100);check(repo.summary(actor,order).get("status").equals("PENDING"),"durable pending fulfillment");Files.writeString(dir.resolve("recover.txt"),"status=PASSED\nnew-JVM/checkout-disabled/expired-lease/original-work/exactly-one-CONFIRM/PENDING=PASSED\n");return 0;
   }
   var identity=ctx.getBean(IIdentityService.class);String suffix=id().substring(0,8),password="Fulfillment-"+id();var actor=identity.register("fulu"+suffix,password,"fulfillment user");var op=identity.initializeOperator("fulop"+suffix,password,"fulfillment operator");
   var o=PaymentCommands.fresh(ctx,actor.userId(),op.userId());
   var a=payments.create(actor.userId(),o.orderId(),id(),null,id());String payment=a.receipt().paymentId(),attempt=a.receipt().attemptId();payments.tick(100);payments.choose(actor.userId(),payment,attempt,id(),"SUCCEEDED",id());payments.tick(100);var fact=channel.fact(payment,attempt);settlement.receive(completed(o,"3"));settlement.applyInbox(100);String wid=work(db,o.orderId(),"3");check(repo.claim(wid)==null,"early team before local success persists dependency");check(count(db,"SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",o.orderId())==0,"early team never fulfills");settlement.observe(fact);due(db,wid);check(repo.claim(wid)==null,"success without A acceptance remains HELD");String event=db.queryForObject("SELECT event_id FROM b_trade_outbox WHERE payment_id=?",String.class,payment);settlement.receive(SettlementCommands.receipt(o,fact.channel(),event,id(),"APPLIED"));settlement.applyInbox(100);due(db,wid);
   FulfillmentWork w;try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var x=pool.submit(()->repo.claim(wid));var y=pool.submit(()->repo.claim(wid));var wx=x.get();var wy=y.get();check((wx==null)!=(wy==null),"concurrent claim only one lease");w=wx!=null?wx:wy;}
   String goods=o.confirmation().conditions().goodsId();var balance=db.queryForMap("SELECT available,reserved,sold,inventory_version FROM b_inventory_account WHERE goods_id=?",goods);var proof=query(pay.order(actor.userId(),o.orderId()),fact.channel(),event,"3");
   var failingDs=failFulfillmentInsert(ds);var failingTx=new TransactionTemplate(new DataSourceTransactionManager(failingDs));failingTx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);boolean failed=false;try{new FulfillmentRepository(failingDs,failingTx,orders,settlement).complete(w,proof);}catch(org.springframework.dao.DataAccessException expected){failed=true;}check(failed&&balance.equals(db.queryForMap("SELECT available,reserved,sold,inventory_version FROM b_inventory_account WHERE goods_id=?",goods))&&count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='CONFIRM'",o.orderId())==0&&count(db,"SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",o.orderId())==1,"failure after inventory reservation and ledger rolls everything back");
   tx.executeWithoutResult(s->{repo.complete(w,proof);check(count(db,"SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",o.orderId())==1,"atomic writes visible before rollback");s.setRollbackOnly();});check(balance.equals(db.queryForMap("SELECT available,reserved,sold,inventory_version FROM b_inventory_account WHERE goods_id=?",goods))&&count(db,"SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",o.orderId())==0&&count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='CONFIRM'",o.orderId())==0&&count(db,"SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",o.orderId())==1,"rollback restores inventory ledger guard order task and fulfillment");
   db.update("UPDATE b_trade_work SET lease_until_ms=0 WHERE work_id=? AND lease_token=?",wid,w.token());repo.complete(w,proof);check(count(db,"SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",o.orderId())==0,"expired completion fenced after locks");db.update("UPDATE b_trade_work SET next_attempt_ms=0 WHERE work_id=?",wid);var next=repo.claim(wid);repo.complete(next,proof);check(pay.order(actor.userId(),o.orderId()).businessStatus().equals("GROUP_COMPLETED")&&repo.summary(actor.userId(),o.orderId()).get("status").equals("PENDING"),"completed group becomes pending fulfillment");check(repo.summary(op.userId(),o.orderId())==null,"fulfillment summary owner isolation");check(count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='CONFIRM'",o.orderId())==1&&count(db,"SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",o.orderId())==0,"one confirm clears only original guard");repo.complete(w,proof);repo.complete(next,proof);
   // Install an owned subsequent guard to test duplicate completion never clears it.
   var orderService=ctx.getBean(cn.zj.zjmarket.domain.order.service.IOrderService.class);var confirmation=orderService.confirm(actor.userId(),o.confirmation().conditions(),id());String newer=orderService.create(actor.userId(),id(),confirmation.confirmationId(),id()).order().orderId();settlement.receive(completed(o,"4"));settlement.applyInbox(100);String newerWork=work(db,o.orderId(),"4");due(db,newerWork);var duplicate=repo.claim(newerWork);repo.complete(duplicate,query(pay.order(actor.userId(),o.orderId()),fact.channel(),event,"4"));check(count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='CONFIRM'",o.orderId())==1&&count(db,"SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",newer)==1,"newer completion preserves subsequent guard");settlement.applyInbox(100);
   var restart=PaymentCommands.fresh(ctx,actor.userId(),op.userId());var ra=payments.create(actor.userId(),restart.orderId(),id(),null,id());String rp=ra.receipt().paymentId(),rt=ra.receipt().attemptId();payments.tick(100);payments.choose(actor.userId(),rp,rt,id(),"SUCCEEDED",id());payments.tick(100);var rf=channel.fact(rp,rt);settlement.observe(rf);String re=db.queryForObject("SELECT event_id FROM b_trade_outbox WHERE payment_id=?",String.class,rp);settlement.receive(SettlementCommands.receipt(restart,rf.channel(),re,id(),"APPLIED"));settlement.applyInbox(100);settlement.receive(completed(restart,"3"));settlement.receive(completed(restart,"4"));settlement.applyInbox(100);String rw=work(db,restart.orderId(),"3");due(db,rw);var rwc=repo.claim(rw);repo.complete(rwc,query(pay.order(actor.userId(),restart.orderId()),rf.channel(),re,"3"));check(count(db,"SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",restart.orderId())==0,"stale A team query waits for current roster version");due(db,rw);var outage=repo.claim(rw);for(int failures=1;failures<=5;failures++){repo.retry(outage);check(count(db,"SELECT COUNT(*) FROM b_fulfillment WHERE order_id=?",restart.orderId())==0,"query outage never confirms inventory");due(db,rw);outage=repo.claim(rw);}check(count(db,"SELECT COUNT(*) FROM b_trade_work WHERE work_id=? AND alerted=TRUE AND failure_count=5",rw)==1,"five query failures alert and remain reclaimable");db.update("UPDATE b_trade_work SET lease_until_ms=0,next_attempt_ms=0 WHERE work_id=? AND lease_token=?",rw,outage.token());var lease=repo.claim(rw);Files.write(dir.resolve("restart.json"),new ContractCodec().encode(Map.of("actor",actor.userId(),"order",restart.orderId(),"payment",rp,"attempt",rt,"work",rw,"token",lease.token())));
   var absent=SettlementCommands.wire(id(),"TEAM_COMPLETED",Map.of("teamId","missing-team-"+id(),"activityId","1","teamVersion","1","outTradeNoList",List.of("missing-order-"+id())),null);settlement.receive(absent);var missingRows=db.queryForList("SELECT work_id FROM b_trade_work WHERE kind='TEAM_COMPLETED' AND evidence_hash=?",absent.hash());check(missingRows.size()==1&&repo.claim(missingRows.getFirst().get("work_id").toString())==null,"missing order completion persisted before ACK without FK loss");
   Files.writeString(dir.resolve("verify.txt"),"status=PASSED\nearly-team/missing-money/missing-A-acceptance/concurrent-claim/full-payment-query/atomic-rollback/injected-insert-failure/query-outage-five-alerts/lease-fencing/PENDING/owner-isolation/duplicate-guard-safety/stale-version/old-event-with-new-cursor=PASSED\nrestart=PREPARED\n");return 0;
  }
 }catch(Exception e){System.err.println("Fulfillment verification failed: "+e.getClass().getSimpleName()+" "+(e.getMessage()!=null&&e.getMessage().startsWith("check:")?e.getMessage():"details withheld"));System.err.println(Arrays.toString(e.getStackTrace()));return 1;}}
}
